package com.example.solarfarm.service;
import com.example.solarfarm.domain.*; import com.example.solarfarm.repository.*; import com.example.solarfarm.ml.*; import com.example.solarfarm.common.Dtos; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class TelemetryService { private final TelemetryRepository telemetry; private final PredictionRepository predictions; private final AlertRepository alerts; private final PanelService panels; private final MlClient ml; public TelemetryService(TelemetryRepository t,PredictionRepository p,AlertRepository a,PanelService ps,MlClient m){telemetry=t;predictions=p;alerts=a;panels=ps;ml=m;}
 @Transactional public Dtos.TelemetryResponse ingest(Dtos.TelemetryRequest request){Panel panel=panels.find(request.panelId());double power=request.vdc1()*request.idc1()+request.vdc2()*request.idc2();telemetry.save(new Telemetry(panel,request.timestamp(),request.vdc1(),request.vdc2(),request.idc1(),request.idc2(),request.irradiance(),request.pvTemperature(),power));MlDtos.MlPrediction m=ml.predict(new MlDtos.MlTelemetry(request.panelId(),request.timestamp(),request.vdc1(),request.vdc2(),request.idc1(),request.idc2(),request.irradiance(),request.pvTemperature()));Prediction prediction=predictions.save(new Prediction(panel,m.timestamp(),m.actual_power_w(),m.expected_power_w(),m.deviation_w(),m.deviation_percent(),m.anomaly(),m.anomaly_score(),m.fault_type(),m.confidence(),m.severity(),m.model_version()));if(m.anomaly())alerts.save(new Alert(panel,prediction,m.fault_type(),m.severity(),"Anomalous PV behavior detected: "+m.fault_type()));panels.update(panel,m.severity(),m.anomaly());return new Dtos.TelemetryResponse(request,map(prediction));}
 public List<Dtos.PredictionResponse> predictions(String panelId){return predictions.findByPanel_PanelIdOrderByTimestampDesc(panelId).stream().map(this::map).toList();} private Dtos.PredictionResponse map(Prediction p){return new Dtos.PredictionResponse(p.getId(),p.getPanel().getPanelId(),p.getTimestamp(),p.getActualPowerW(),p.getExpectedPowerW(),p.getDeviationW(),p.getDeviationPercent(),p.isAnomaly(),p.getAnomalyScore(),p.getFaultType(),p.getConfidence(),p.getSeverity(),p.getModelVersion());}}
